/** Generated by scripts/generate-blog-audio.mjs into the public `blog-audio` bucket. */
export type BlogAudioLocale = "az" | "ru" | "en" | "de";

export type BlogAudioEntry = {
  slug: string;
  lang: BlogAudioLocale;
  url: string;
  duration_seconds: number;
  bytes: number;
  hash: string;
  voice: string;
  generated_at: string;
};

export const BLOG_AUDIO_BUCKET = "blog-audio";
export const BLOG_AUDIO_CACHE_TAG = "blog-audio";

const inLanguage: Record<BlogAudioLocale, string> = {
  az: "az-AZ",
  ru: "ru-RU",
  en: "en-US",
  de: "de-DE",
};

export const blogAudioLabels: Record<BlogAudioLocale, string> = {
  az: "Yazını dinlə",
  ru: "Послушать статью",
  en: "Listen to this article",
  de: "Artikel anhören",
};

export function blogAudioManifestUrl(supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL) {
  if (!supabaseUrl) return null;
  return `${supabaseUrl.replace(/\/$/, "")}/storage/v1/object/public/${BLOG_AUDIO_BUCKET}/manifest.json`;
}

function isAudioLocale(value: unknown): value is BlogAudioLocale {
  return value === "az" || value === "ru" || value === "en" || value === "de";
}

function isEntry(value: unknown): value is BlogAudioEntry {
  if (!value || typeof value !== "object") return false;
  const entry = value as Record<string, unknown>;
  return (
    typeof entry.slug === "string" &&
    isAudioLocale(entry.lang) &&
    typeof entry.url === "string" &&
    entry.url.startsWith("https://") &&
    typeof entry.duration_seconds === "number" &&
    entry.duration_seconds > 0
  );
}

export function findBlogAudio(manifest: unknown, slug: string, locale: string): BlogAudioEntry | null {
  if (!isAudioLocale(locale)) return null;
  const entries = (manifest as { entries?: unknown } | null)?.entries;
  if (!Array.isArray(entries)) return null;
  return (
    entries.find((entry): entry is BlogAudioEntry => isEntry(entry) && entry.slug === slug && entry.lang === locale) ??
    null
  );
}

/** ISO 8601 duration, e.g. 161 -> "PT2M41S". */
export function isoDuration(seconds: number) {
  const total = Math.max(1, Math.round(seconds));
  const minutes = Math.floor(total / 60);
  const rest = total % 60;
  return `PT${minutes ? `${minutes}M` : ""}${rest || !minutes ? `${rest}S` : ""}`;
}

/** Player label, e.g. 161 -> "2:41". */
export function formatAudioDuration(seconds: number) {
  const total = Math.max(1, Math.round(seconds));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
}

export function blogAudioSchema(entry: BlogAudioEntry, name: string) {
  return {
    "@type": "AudioObject",
    name,
    contentUrl: entry.url,
    encodingFormat: "audio/mpeg",
    duration: isoDuration(entry.duration_seconds),
    inLanguage: inLanguage[entry.lang],
  };
}

/** Reads the manifest through the Next data cache; any failure means "no audio". */
export async function getBlogAudio(slug: string, locale: string): Promise<BlogAudioEntry | null> {
  const url = blogAudioManifestUrl();
  if (!url || !isAudioLocale(locale)) return null;
  try {
    const response = await fetch(url, {
      // Fresh audio after local generate; production still revalidates hourly.
      ...(process.env.NODE_ENV === "development"
        ? { cache: "no-store" as const }
        : { next: { revalidate: 3600, tags: [BLOG_AUDIO_CACHE_TAG] } }),
    });
    if (!response.ok) return null;
    return findBlogAudio(await response.json(), slug, locale);
  } catch {
    return null;
  }
}
